mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("[1,2,3,4,5,null,6]","1,2,4,5,3,6"),
        ("[1,2,3]","1,2,3"),
        ("[1]","1"),
        ("[2,1,3]","2,1,3"),
        ("[1,null,2,null,3]","1,2,3"),
        ("  \n[1,2,3,4,5,null,6]\n  ","1,2,4,5,3,6"),
        ("\n[1,null,2,null,3]\n","1,2,3")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS tree-preorder");
}
